package mdn.jh.automation.devices.mqtt;
import org.w3c.dom.*;import mdn.jh.automation.io.DataComponentStub;import mdn.jh.automation.io.logic.InputDefinition;import mdn.jh.automation.io.sink.DataSink;
public class MqttDataSink extends DataSink{private static final long serialVersionUID=1L;private transient MqttBrokerDevice device;private String topic="",valueType="string",lastPayload;private int qos;private boolean retained,valid=true;public MqttDataSink(){super(new InputDefinition[0]);}public MqttDataSink(MqttBrokerDevice d,String topic,int qos,boolean retained,String type){super(new InputDefinition[]{new InputDefinition("Value",map(type))});configure(d,topic,qos,retained,type);}private static int map(String t){return"boolean".equals(t)?DataComponentStub.TYPE_BOOLEAN_IO:"number".equals(t)?DataComponentStub.TYPE_DOUBLE_IO:DataComponentStub.TYPE_STRING_IO;}public void configure(MqttBrokerDevice d,String t,int q,boolean r,String type){if(t==null||t.trim().isEmpty())throw new IllegalArgumentException("MQTT topic is required");if(q<0||q>2)throw new IllegalArgumentException("QoS must be 0, 1, or 2");device=d;topic=t.trim();qos=q;retained=r;valueType=type;setStatusMessage("Publish to "+topic+" (QoS "+qos+(retained?", retained":"")+")");}public void setDevice(MqttBrokerDevice d){device=d;}@Override public void updateCycle(){if(!isInputInUse(0)||getInputData(0)==null||!getInputData(0).isDataValid())return;String payload="boolean".equals(valueType)?Boolean.toString(getInputData(0).getOutputAsBoolean()):"number".equals(valueType)?Double.toString(getInputData(0).getOutputAsNumber()):getInputData(0).getOutputAsString();if(payload.equals(lastPayload))return;try{device.publish(topic,payload,qos,retained);lastPayload=payload;valid=true;myOutput.setValue("published");myOutput.setDataValid(true);}catch(Exception e){valid=false;myOutput.setValue("failed: "+e.getMessage());myOutput.setDataValid(false);}}@Override public boolean isDataValid(){return valid;}@Override public javax.swing.JPanel getSpecificDetailsPanel(){return null;}@Override public Node getStorageXML(Document d){Element root=getStorageDataSink(d),c=d.createElement("MqttSink");c.setAttribute("topic",topic);c.setAttribute("qos",Integer.toString(qos));c.setAttribute("retained",Boolean.toString(retained));c.setAttribute("valueType",valueType);root.appendChild(c);return root;}@Override public void initSpecific(Node n){NodeList l=n.getChildNodes();for(int i=0;i<l.getLength();i++)if("MqttSink".equals(l.item(i).getNodeName())){Node c=l.item(i);topic=c.getAttributes().getNamedItem("topic").getNodeValue();qos=Integer.parseInt(c.getAttributes().getNamedItem("qos").getNodeValue());retained=Boolean.parseBoolean(c.getAttributes().getNamedItem("retained").getNodeValue());valueType=c.getAttributes().getNamedItem("valueType").getNodeValue();defineInputs(new InputDefinition[]{new InputDefinition("Value",map(valueType))});setStatusMessage("Publish to "+topic+" (QoS "+qos+(retained?", retained":"")+")");}}}
